import React,{useEffect,useMemo,useState} from 'react';
import {createRoot} from 'react-dom/client';import {BrowserRouter,useNavigate,useLocation,useParams,Routes,Route,Link,Navigate} from 'react-router-dom';
import {LayoutDashboard,ShoppingCart,Users,UserRound,BarChart3,Settings,Truck,Plus,Search,Bell,Sun,Moon,MapPin,Package,Menu,X,ArrowUpRight,Trash2,Edit3,Play,Pause} from 'lucide-react';import {AreaChart,Area,XAxis,YAxis,Tooltip,ResponsiveContainer} from 'recharts';import './styles.css';import {authService,orderService,customerService,driverService,normalizeCustomer,linkOrdersToDrivers,normalizeDriver} from './services';import type {AuthUser,Order,Customer,Driver,ProfileUpdate,Status,CustomerStatus} from './types';
import LeafletTrackingMap from './components/LeafletTrackingMap';
import {deliveryLocations,deliveryFeeFor} from './deliveryFees';
const seedNames=['Rami Haddad','Maya Khoury','Nour Saad','Karim Tabet','Lina Nassar','Omar Daher','Sara Fares','Tarek Mansour','Hiba Younes','Jad Khalil'];const cities=deliveryLocations.map(location=>location.city);
/* 2: hna mnwahhed l-destination lal tables w details bala commas zeyde. */
const cleanDestination=(...parts:string[])=>parts.filter((part):part is string=>typeof part==='string').map(part=>part.replace(/,/g,'').replace(/\s+/g,' ').trim()).filter(Boolean).join(' ');
const destinationFor=(order:Pick<Order,'address'|'city'>)=>cleanDestination(order.address,order.city);
const statusOptions:Status[]=['Delivered','In Transit','Processing','Delayed'];
const progressForStatus=(status:Status)=>({Delivered:100,'In Transit':65,Processing:20,Delayed:40}[status]);
const safeStatus=(status:unknown):Status=>statusOptions.includes(status as Status)?status as Status:'Processing';
// Today's local calendar date keeps the date input and submit validation in sync with the user.
const todayLocalDate=()=>{const now=new Date();return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`};
const safeCustomer=(customer:Partial<Customer>|null|undefined,index:number):Customer=>normalizeCustomer(customer||{},index);
// هون منحسب الأرقام من الداتا الحالية، مش من أرقام ثابتة.
const orderDate=(order:Order)=>new Date(order.date||order.createdAt||order.updatedAt||0);
const orderTotals=(orders:Order[])=>({total:orders.length,inTransit:orders.filter(o=>o.status==='In Transit').length,delivered:orders.filter(o=>o.status==='Delivered').length,revenue:orders.reduce((sum,o)=>sum+Number(o.total||0),0)});
const dailyOrders=(orders:Order[])=>{const days=Array.from({length:7},(_,i)=>{const date=new Date();date.setHours(0,0,0,0);date.setDate(date.getDate()-(6-i));return date});return days.map(date=>{const key=date.toISOString().slice(0,10);return {day:date.toLocaleDateString(undefined,{weekday:'short'}),orders:orders.filter(o=>orderDate(o).toISOString().slice(0,10)===key).length,revenue:orders.filter(o=>orderDate(o).toISOString().slice(0,10)===key).reduce((sum,o)=>sum+Number(o.total||0),0)}})};
/* Hawn form jdide: kel l-fields btballesh fadiye, w l-defaults btet3abba bas bel edit/save. */
const blankCustomer=():Customer=>({id:crypto.randomUUID(),name:'',fullName:'',email:'',phone:'',address:'',city:'',area:'',company:'',type:'' as Customer['type'],joinedDate:'',notes:'',preferredPayment:'',ordersCount:0,totalSpent:0,lastOrder:'',status:'' as CustomerStatus});
/* 3: hna seed data b7ot demo orders 3ashan dashboard ybda m7louq w user ma y7tajsh 3al initial setup. */
/* 5: hna seed function b7ot generate orders w statuses 3ashan UI ykoun active. */
const seed=():Order[]=>Array.from({length:24},(_,i)=>({id:`ORD-${1048-i}`,customer:seedNames[i%10],customerId:`cust-${String((i%10)+1).padStart(3,'0')}`,city:cities[i%7],subtotal:Math.round(35+i*17.4),deliveryFee:deliveryFeeFor(cities[i%7]),total:Math.round(35+i*17.4)+deliveryFeeFor(cities[i%7]),status:(['Delivered','In Transit','Processing','Delayed'] as Status[])[i%4],date:`2026-09-${String(23-i%20).padStart(2,'0')}`,items:i%4+1,progress:[100,65,20,40][i%4],trackingNumber:`LB${849200+i}`,phone:`+961 70 ${100000+i}`,address:`${12+i} Hamra Street`,paymentMethod:i%2?'Cash on delivery':'Credit card',deliveryWindow:'10:00 - 14:00',notes:'Handle with care',products:[{name:i%2?'Wireless headphones':'Coffee beans',quantity:i%4+1,price:Math.round(15+i)}],driver:['Fadi','Maya','Rami'][i%3],createdAt:`2026-09-${String(20-i%10).padStart(2,'0')}T09:00:00Z`,updatedAt:`2026-09-${String(23-i%10).padStart(2,'0')}T12:00:00Z`}));
/* 7: hna root app w router b7ot navigation w layout 3ashan dashboard y3mil work. */
function App(){const[dark,setDark]=useState(()=>localStorage.getItem('routely-theme')==='dark'||(!localStorage.getItem('routely-theme')&&window.matchMedia('(prefers-color-scheme: dark)').matches));const[mobile,setMobile]=useState(false);const[collapsed,setCollapsed]=useState(()=>localStorage.getItem('routely-sidebar')==='collapsed');const[panel,setPanel]=useState<'search'|'notifications'|'profile'|null>(null);const[q,setQ]=useState('');const[orders,setOrders]=useState<Order[]>([]);const[user,setUser]=useState<AuthUser|null>(()=>authService.current());useEffect(()=>{localStorage.setItem('routely-theme',dark?'dark':'light');document.documentElement.classList.toggle('dark-mode',dark)},[dark]);useEffect(()=>{localStorage.setItem('routely-sidebar',collapsed?'collapsed':'expanded')},[collapsed]);useEffect(()=>{const close=(e:KeyboardEvent)=>{if(e.key==='Escape'){setMobile(false);setPanel(null)}};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close)},[]);useEffect(()=>{orderService.list().then(x=>setOrders(x.length?x:seed())).catch(()=>setOrders(seed()))},[]);if(!user)return <Routes><Route path="/register" element={<Register onLogin={setUser}/>}/><Route path="*" element={<Login onLogin={setUser}/>}/></Routes>;const logout=()=>{authService.logout();setUser(null)};const userName=typeof user.name==='string'&&user.name?user.name:typeof user.email==='string'&&user.email?user.email:'User';return <div className={`${dark?'app dark':'app'}${collapsed?' sidebar-collapsed':''}`}><Sidebar user={user} mobile={mobile} collapsed={collapsed} close={()=>setMobile(false)} toggle={()=>window.innerWidth<=700?setMobile(v=>!v):setCollapsed(v=>!v)}/>{mobile&&<button className="sidebarOverlay" aria-label="Close navigation" onClick={()=>setMobile(false)}/>}<main><header><div><div className="eyebrow">LEBANON • OPERATIONS</div><h1>{pageTitle()}</h1></div><div className="actions"><button aria-label="Search" className="icon" onClick={()=>setPanel(panel==='search'?null:'search')}><Search/></button><button aria-label="Notifications" className="icon" onClick={()=>setPanel(panel==='notifications'?null:'notifications')}><Bell/><i/></button><button aria-label="Toggle dark mode" className="icon" onClick={()=>setDark(!dark)}>{dark?<Sun/>:<Moon/>}</button><button className="avatar" onClick={()=>setPanel(panel==='profile'?null:'profile')}>{userName.split(' ').map(part=>part[0]).join('').slice(0,2)}</button></div>{panel==='search'&&<div className="headerPanel searchPanel"><div className="search"><Search size={16}/><input autoFocus placeholder="Search orders, customers, tracking..." value={q} onChange={e=>setQ(e.target.value)}/></div>{q&&orders.filter(o=>Object.values(o).join(' ').toLowerCase().includes(q.toLowerCase())).slice(0,5).map(o=><Link key={o.id} to={'/orders/'+o.id} onClick={()=>setPanel(null)}><b>{o.id}</b><span>{o.customer} · {o.trackingNumber}</span></Link>)}</div>}{panel==='notifications'&&<div className="headerPanel"><b>Notifications</b><p>3 shipments need attention</p><p>Driver Fadi is near Beirut</p><Link to="/tracking" onClick={()=>setPanel(null)}>Open tracking</Link></div>}{panel==='profile'&&<div className="headerPanel"><b>{userName}</b><p>{user.role} · {user.city}</p><Link to="/profile" onClick={()=>setPanel(null)}>My profile</Link><button className="btn" onClick={logout}>Log out</button></div>}</header><Routes><Route path="/" element={<Dashboard/>}/><Route path="/orders" element={<Orders/>}/><Route path="/orders/new" element={<OrderForm/>}/><Route path="/orders/:id/edit" element={<OrderForm/>}/><Route path="/orders/:id" element={<OrderDetails/>}/><Route path="/tracking" element={<Tracking/>}/><Route path="/drivers" element={<Drivers/>}/><Route path="/customers" element={<Customers/>}/><Route path="/customers/new" element={<Customers/>}/><Route path="/customers/:id/edit" element={<CustomerEdit/>}/><Route path="/customers/:id" element={<CustomerDetails/>}/><Route path="/analytics" element={<Analytics/>}/><Route path="/settings" element={<SettingsPage/>}/><Route path="/profile" element={<ProfilePage user={user} onUpdate={setUser} onLogout={logout}/>}/><Route path="*" element={<Navigate to="/" replace/>}/></Routes></main></div>}
/* 2: hna pageTitle b7ot route label 3ashan UX ykoun clear. */
function pageTitle(){const p=useLocation().pathname;return p==='/'?'Good morning':p.includes('tracking')?'Live tracking':p.includes('drivers')?'Drivers':p.includes('orders')?'Orders':p.includes('customers')?'Customers':p.includes('analytics')?'Analytics':'Settings'}
/* 5: hna sidebar b7ot nav w workspace info 3ashan users ykounu easy. */
function Sidebar({user,mobile,collapsed,close,toggle}:{user:AuthUser;mobile:boolean;collapsed:boolean;close:()=>void;toggle:()=>void}){const pathname=useLocation().pathname;const[orderCount,setOrderCount]=useState(0);const[activeCount,setActiveCount]=useState(0);useEffect(()=>{const refresh=()=>orderService.list().then(data=>{setOrderCount(data.length);setActiveCount(data.filter(order=>order.status==='In Transit').length)}).catch(()=>{});refresh();const timer=window.setInterval(refresh,3000);return()=>window.clearInterval(timer)},[]);/* 3: hna green logo howwe l-toggle taba3 l-sidebar la ydal bayyen ma3 l-scroll. */const nav=[['/','Overview',LayoutDashboard],['/orders','Orders',ShoppingCart],['/tracking','Tracking',Truck],['/drivers','Drivers',UserRound],['/customers','Customers',Users],['/analytics','Analytics',BarChart3]] as const;const identity=typeof user.name==='string'&&user.name?user.name:typeof user.email==='string'&&user.email?user.email:'User';const initials=identity.split(' ').map(part=>part[0]).join('').slice(0,2).toUpperCase();return <aside className={(mobile?'open ':'')+(collapsed?'collapsed':'')}><div className="brand"><button className="logo" aria-label={mobile?'Close navigation':collapsed?'Expand sidebar':'Collapse sidebar'} onClick={toggle}><Truck size={20}/></button><b>Route<span>ly</span></b></div><div className="workspace"><span className="wsdot"/> <span>Beirut Hub</span></div><nav>{nav.map(([to,label,I])=><Link title={label} onClick={close} className={pathname===to?'active':''} to={to} key={to}><I size={18}/><span>{label}</span>{to==='/orders'&&orderCount>0&&<em className="count">{orderCount}</em>}{to==='/tracking'&&activeCount>0&&<em className="count">{activeCount}</em>}</Link>)}</nav><div className="navbottom"><Link title="Settings" onClick={close} to="/settings"><Settings size={18}/><span>Settings</span></Link><div className="support">Need help?<small>Visit our support center</small></div><Link className="profile" title="Open profile" onClick={close} to="/profile"><div className="avatar">{initials}</div><b>{user.name||user.email||'User'}<small>{user.role||'User'}</small></b></Link></div></aside>}
/* 7: hna status badge b7ot visual feedback 3ashan order status yb2a clear. */
function Badge({status}:{status?:Status}){const normalized=safeStatus(status);return <span className={'badge '+normalized.toLowerCase().replace(' ','-')}><i/>{normalized}</span>}
/* 3: hna order table b7ot list w actions 3ashan manage orders bser3a. */
function OrderTable({rows,onDelete,onEdit}:{rows:Order[];onDelete?:(id:string)=>void;onEdit?:(id:string)=>void}){return <div className="tablewrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Destination</th><th>Tracking</th><th>Date</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody>{rows.map(o=><tr key={o.id}><td><Link className="orderid" to={'/orders/'+o.id}>{o.id}</Link></td><td>{o.customer||'Unknown'}<small className="subline">{o.phone||'No phone'}</small></td><td>{destinationFor(o)}</td><td>{o.trackingNumber||'—'}</td><td>{o.date||'—'}</td><td><b>${(o.total||0).toFixed(2)}</b><small className="subline">Fee: ${(o.deliveryFee||0).toFixed(2)}</small></td><td><Badge status={o.status||'Processing'}/></td><td><button className="icon" aria-label={`Edit ${o.id}`} onClick={()=>onEdit?.(o.id)}><Edit3 size={15}/></button><button className="icon" aria-label={`Delete ${o.id}`} onClick={()=>onDelete?.(o.id)}><Trash2 size={15}/></button></td></tr>)}</tbody></table></div>}
/* 5: hna dashboard b7ot KPIs w chart 3ashan user yshouf performance fast. */
function Dashboard(){const[rows,setRows]=useState<Order[]>([]);const nav=useNavigate();useEffect(()=>{orderService.list().then(setRows).catch(()=>setRows([]))},[]);const totals=orderTotals(rows);const active=rows.find(o=>o.status==='In Transit')||rows[0];const chart=dailyOrders(rows);return <div className="page"><div className="welcome"><div><p className="muted">{new Date().toLocaleDateString(undefined,{weekday:'long',year:'numeric',month:'long',day:'numeric'})}</p><h2>Your logistics at a glance.</h2></div><Link className="btn primary" to="/orders/new"><Plus size={17}/>Create order</Link></div><div className="stats"><Stat label="Total orders" value={String(totals.total)}/><Stat label="In transit" value={String(totals.inTransit)}/><Stat label="Delivered" value={String(totals.delivered)}/><Stat label="Revenue" value={`$${totals.revenue.toFixed(2)}`}/></div><div className="grid2"><section className="card chartcard"><h3>Orders overview</h3><p className="muted">Order volume for the last 7 days</p><ResponsiveContainer width="100%" height={240}><AreaChart data={chart}><XAxis dataKey="day"/><YAxis allowDecimals={false}/><Tooltip/><Area type="monotone" dataKey="orders" stroke="#635bff" fill="#635bff" fillOpacity={.15}/></AreaChart></ResponsiveContainer></section><MapCard order={active}/></div><section className="card tablecard"><div className="cardtitle"><h3>Recent orders</h3><Link to="/orders">View all orders <ArrowUpRight size={15}/></Link></div>{rows.length?<OrderTable rows={[...rows].sort((a,b)=>orderDate(b).getTime()-orderDate(a).getTime()).slice(0,5)} onEdit={id=>nav('/orders/'+id+'/edit')}/>:<p className="muted">No orders yet.</p>}</section></div>}
/* 2: hna stat card b7ot metrics 3ashan summary y7a9eq. */
function Stat({label,value}:{label:string;value:string}){return <div className="stat"><div className="stathead">{label}<Package size={18}/></div><strong>{value}</strong><small>? 12.5% <span>vs last month</span></small></div>}
/* 7: hna map card b7ot track vibe 3ashan route visuals yb2a easy. */
function MapCard({order}:{order?:Order}){return <section className="card"><div className="cardtitle"><h3>Live tracking</h3><Link to="/tracking">Open tracker</Link></div><LeafletTrackingMap order={order}/></section>}
/* 3: hna orders page b7ot search w CRUD 3ashan operations ykounu smooth. */
function Orders(){const[rows,setRows]=useState<Order[]>([]);const[q,setQ]=useState('');const nav=useNavigate();const load=()=>orderService.list().then(setRows).catch(()=>setRows([]));useEffect(()=>{load()},[]);const remove=async(id:string)=>{if(confirm('Delete this order?')){await orderService.remove(id);await load()}};return <div className="page"><div className="toolbar"><div><p className="muted">Manage and track every shipment</p><h2>All orders</h2></div><Link className="btn primary" to="/orders/new"><Plus/>New order</Link></div><div className="card tablecard"><div className="filters"><div className="search"><Search size={17}/><input placeholder="Search orders..." value={q} onChange={e=>setQ(e.target.value)}/></div></div><OrderTable rows={rows.filter(o=>Object.values(o).join(' ').toLowerCase().includes(q.toLowerCase()))} onDelete={remove} onEdit={id=>nav('/orders/'+id+'/edit')}/></div></div>}
/* 5: hna form b7ot create/edit order w save fallback 3ashan data keep stable. */
function OrderForm(){const nav=useNavigate();const {id}=useParams();const editing=Boolean(id&&id!=='new');const[error,setError]=useState('');const[original,setOriginal]=useState<Order|null>(null);const[drivers,setDrivers]=useState<Driver[]>([]);const[customers,setCustomers]=useState<Customer[]>([]);const[form,setForm]=useState<Partial<Order>>({});useEffect(()=>{driverService.list().then(setDrivers);customerService.list().then(setCustomers).catch(()=>setCustomers([]));if(editing)orderService.list().then(x=>{const found=x.find(o=>o.id===id);if(found){setOriginal(found);setForm(found)}else setError('Order not found.')}).catch(()=>setError('Could not load this order.'))},[editing,id]);const set=(k:keyof Order,v:string)=>setForm(f=>({...f,[k]:k==='total'||k==='subtotal'||k==='deliveryFee'||k==='items'||k==='progress'?Number(v):k==='status'?safeStatus(v):v}));// Hawn mn3abbe data l-zaboun marra bas ykhtar customer, w ma mnmas l-fields ba3den bala selection jdeede.
const selectCustomer=(customerId:string)=>{const customer=customers.find(c=>c.id===customerId);if(!customer){setForm(f=>({...f,customerId:customerId||undefined}));return}setForm(f=>{const city=customer.city||f.city||'';const subtotal=Number(f.subtotal)||0;const fee=city?deliveryFeeFor(city):f.deliveryFee;return {...f,customerId:customer.id,customer:customer.name||customer.fullName||f.customer||'',customerEmail:customer.email||f.customerEmail||'',phone:customer.phone||f.phone||'',address:customer.address||f.address||'',city,area:customer.area||f.area||'',paymentMethod:customer.preferredPayment||f.paymentMethod||'',deliveryFee:fee,total:city?subtotal+Number(fee||0):f.total}})};const changeCity=(city:string)=>setForm(f=>{const fee=deliveryFeeFor(city);const subtotal=Number(f.subtotal??(editing?f.total:0))||0;return {...f,city,deliveryFee:city?fee:undefined,total:city?subtotal+fee:(editing?f.total:undefined),subtotal:city?subtotal:f.subtotal}});return <div className="page formpage"><div className="toolbar"><div><p className="muted">Orders / {editing?'Edit':'New'} order</p><h2>{editing?'Edit order':'Create new order'}</h2></div></div><form className="card form" noValidate onSubmit={async e=>{e.preventDefault();setError('');try{const today=todayLocalDate();const selected=drivers.find(d=>d.id===form.driverId);const payload={...form,subtotal:Number(form.subtotal)||0,deliveryFee:Number(form.deliveryFee)||0,total:Number(form.total)||0,area:form.area||'',driverId:form.driverId||undefined,driver:selected?.name||form.driver||'Unassigned',customerId:form.customerId||undefined,status:safeStatus(form.status),...(editing&&original&&form.status!==original.status&&form.progress===original.progress?{progress:progressForStatus(safeStatus(form.status))}: {})};if(!payload.customer||!payload.city||!payload.address||!payload.phone){setError('Please complete customer, phone, address and city.');return}if(!form.status||form.subtotal===undefined){setError('Please choose a status and enter a subtotal.');return}if(!payload.date){setError('Please choose a delivery date.');return}if((!editing||payload.date!==original?.date)&&payload.date<today){setError('Delivery date cannot be before today. Please choose today or a future date.');return}if(editing&&id)await orderService.update(id,payload);else await orderService.create({id:`ORD-${Date.now()}`,...payload} as Order);nav('/orders')}catch(err){setError(err instanceof Error?err.message:'Could not save order.')}}}><section className="formsection"><h3>Recipient details</h3><p className="muted">Who should receive this shipment?</p><div className="formgrid"><label>Customer<select required value={form.customerId||(form.customer?'legacy':'')} onChange={e=>selectCustomer(e.target.value)}><option value="">Select customer</option>{customers.map(c=><option key={c.id} value={c.id}>{c.name||c.fullName||'Unknown customer'}</option>)}{form.customer&&!customers.some(c=>c.id===form.customerId)&&<option value={form.customerId||'legacy'}>{form.customer}</option>}</select></label><label>Phone<input required value={form.phone||''} onChange={e=>set('phone',e.target.value)}/></label><label>City / village<select required value={form.city||''} onChange={e=>changeCity(e.target.value)}><option value="">Select city / village</option>{cities.map(city=><option key={city}>{city}</option>)}</select></label><label>Area / neighborhood<input value={form.area||''} placeholder="e.g. Mar Mikhael" onChange={e=>set('area',e.target.value)}/></label><label className="full">Address<input required value={form.address||''} onChange={e=>set('address',e.target.value)}/></label></div></section><section className="formsection"><h3>Delivery planning</h3><p className="muted">Assign a driver and set the shipment schedule.</p><div className="formgrid"><label>Driver<select value={form.driverId||''} onChange={e=>{const d=drivers.find(x=>x.id===e.target.value);setForm(f=>({...f,driverId:e.target.value,driver:d?.name||'Unassigned'}))}}><option value="">Select driver</option>{drivers.filter(d=>d.status!=='Offline').map(d=><option key={d.id} value={d.id}>{d.name} - {d.currentArea}</option>)}</select></label><label>Status<select required value={form.status||''} onChange={e=>set('status',e.target.value)}><option value="">Select status</option>{statusOptions.map(status=><option key={status}>{status}</option>)}</select></label><label>Delivery date<input type="date" required min={todayLocalDate()} value={form.date||''} onChange={e=>set('date',e.target.value)}/></label><label>Subtotal<input type="number" min="0" step="0.01" required value={form.subtotal??''} onChange={e=>{const subtotal=Number(e.target.value);setForm(f=>({...f,subtotal,total:subtotal+(Number(f.deliveryFee)||0)}))}}/></label><label>Delivery fee <small>(automatic)</small><input readOnly className="readonly" value={form.city&&form.deliveryFee!==undefined?`${Number(form.deliveryFee).toFixed(2)} USD`:``}/></label><label>Total <small>(subtotal + fee)</small><input readOnly className="readonly" value={form.total!==undefined?`${Number(form.total).toFixed(2)} USD`:``}/></label><label>Payment method<select value={form.paymentMethod||''} onChange={e=>set('paymentMethod',e.target.value)}><option value="">Select payment method</option><option>Cash on delivery</option><option>Credit card</option><option>Bank transfer</option></select></label></div><p className="muted">Delivery fee follows the selected Lebanese city/village and cannot be edited here.</p></section><section className="formsection"><h3>Order notes</h3><div className="formgrid"><label className="full">Items / product details<textarea value={form.productDetails||''} onChange={e=>setForm(f=>({...f,productDetails:e.target.value}))}/></label><label className="full">Notes<textarea value={form.notes||''} onChange={e=>set('notes',e.target.value)}/></label></div></section>{error&&<p className="error">{error}</p>}<div className="formactions"><button type="button" className="btn" onClick={()=>nav('/orders')}>Cancel</button><button className="btn primary">{editing?'Save changes':'Create order'}</button></div></form></div>}
/* 2: hna order details page b7ot full view w progress 3ashan tracking. */
function OrderDetails(){const id=useLocation().pathname.split('/').pop()!;const[order,setOrder]=useState<Order|null>(null);useEffect(()=>{orderService.list().then(x=>setOrder(x.find(o=>o.id===id)||seed().find(o=>o.id===id)||null))},[id]);const changeStatus=async(status:Status)=>{if(!order)return;const progress=order.progress===progressForStatus(safeStatus(order.status))?progressForStatus(status):order.progress;const updated=await orderService.update(order.id,{status,progress});setOrder({...order,...updated,status,progress})};if(!order)return <div className="page"><h2>Order not found</h2></div>;return <div className="page"><Link className="back" to="/orders">â† Back to orders</Link><div className="detailhead"><div><p className="muted">Order details · {order.trackingNumber}</p><h2>{order.id} <Badge status={order.status}/></h2></div><div className="formactions"><label>Status<select value={safeStatus(order.status)} onChange={e=>changeStatus(safeStatus(e.target.value))}>{statusOptions.map(status=><option key={status}>{status}</option>)}</select></label><Link className="btn primary" to={'/orders/'+id+'/edit'}>Edit order</Link></div></div><div className="grid2"><section className="card"><h3>Delivery progress</h3><div className="progress"><div style={{width:order.progress+'%'}}/></div><p>{order.progress}% complete · {cleanDestination(order.city)}</p><div className="detailinfo"><div><small>Recipient</small><b>{order.customer}</b><span>{order.phone}</span></div><div><small>Address</small><b>{cleanDestination(order.address)}</b><span>{order.deliveryWindow}</span></div><div><small>Payment</small><b>{order.paymentMethod}</b><span>Driver: {order.driver}</span></div><div><small>Products</small><b>{order.products?.map(p=>`${p.name} Ã—${p.quantity}`).join(', ')}</b><span>{order.notes||'No notes'}</span></div></div><div className="orderSummary"><span>Subtotal <b>${(order.subtotal??order.total).toFixed(2)}</b></span><span>Delivery fee <b>${(order.deliveryFee||0).toFixed(2)}</b></span><strong>Total <b>${order.total.toFixed(2)}</b></strong></div></section><MapCard order={order}/></div></div>}
/* 7: hna tracking section b7ot simulation updates 3ashan live view active. */
function Tracking(){const[rows,setRows]=useState<Order[]>([]);const[selected,setSelected]=useState('');const[running,setRunning]=useState(true);useEffect(()=>{orderService.list().then(data=>{setRows(data);setSelected(data.find(o=>o.status==='In Transit')?.id||data[0]?.id||'')})},[]);useEffect(()=>{if(!running)return;const timer=setInterval(()=>setRows(current=>{const next=current.map(o=>o.id===selected&&o.progress<100?{...o,progress:Math.min(100,o.progress+2),status:safeStatus(o.progress+2>=100?'Delivered':'In Transit')}:o);const changed=next.find(o=>o.id===selected);if(changed)void orderService.update(changed.id,{progress:changed.progress,status:changed.status});return next}),1000);return()=>clearInterval(timer)},[running,selected]);const active=rows.find(o=>o.id===selected);return <div className="page"><div className="toolbar"><div><p className="muted">Provider-isolated tracking simulator</p><h2>Live shipment tracking</h2></div><button className="btn" onClick={()=>setRunning(!running)}>{running?<Pause size={16}/>:<Play size={16}/>} {running?'Pause simulation':'Resume simulation'}</button></div><div className="grid2 trackinggrid"><section className="card shipmentlist"><div className="cardtitle"><div><h3>Active shipments</h3><p>Select a shipment to inspect its route</p></div><span className="count">{rows.filter(o=>o.status==='In Transit'||o.id===selected).length}</span></div><div className="trackingrows">{rows.filter(o=>o.status==='In Transit'||o.id===selected).slice(0,8).map(o=><button type="button" aria-pressed={o.id===selected} className={'trackingrow '+(o.id===selected?'selected':'')} key={o.id} onClick={()=>setSelected(o.id)}><span className="trackingidentity"><b>{o.id}</b><small>{cleanDestination(o.customer,o.city)}</small></span><span className="trackingstatus"><Badge status={o.status}/><strong>{o.progress}%</strong></span><span className="trackingprogress" aria-hidden="true"><i style={{width:`${o.progress}%`}}/></span></button>)}</div></section><section className="card trackingdetail"><h3>{active?.id||'Select a shipment'}</h3><p className="muted">{active?cleanDestination(active.customer,active.city,'Lebanon'):'Choose an active shipment to view its route'}</p><LeafletTrackingMap order={active}/></section></div></div>}
/* 3: hna customers page b7ot CRUD w search 3ashan manage clients. */
function customerOrders(customer:Customer,orders:Order[]){return orders.filter(o=>(o.customerId&&o.customerId===customer.id)||(o.customerEmail&&customer.email&&o.customerEmail.toLowerCase()===customer.email.toLowerCase())||(!o.customerId&&!o.customerEmail&&o.customer===customer.name));}
function CustomerModal({initial,metrics,onClose,onSaved}:{initial:Customer|null;metrics:Pick<Customer,'ordersCount'|'totalSpent'|'lastOrder'>;onClose:()=>void;onSaved:(customer:Customer)=>void}){const editing=Boolean(initial);const [customer,setCustomer]=useState<Customer>(()=>initial||blankCustomer());const [error,setError]=useState('');const [saving,setSaving]=useState(false);useEffect(()=>{const close=(event:KeyboardEvent)=>event.key==='Escape'&&onClose();window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close)},[onClose]);const update=(field:keyof Customer,value:string)=>setCustomer(current=>({...current,[field]:value}));const save=async(event:React.FormEvent)=>{event.preventDefault();setError('');const name=(customer.fullName||customer.name).trim();if(!name){setError('Please enter the customer name.');return}if(customer.email&&!/^\\S+@\\S+\\.\\S+$/.test(customer.email)){setError('Please enter a valid email address.');return}if(!customer.phone.trim()){setError('Please enter a phone number.');return}setSaving(true);try{const next=normalizeCustomer({...customer,name,fullName:name,...metrics});const saved=editing?await customerService.update(next.id,next):await customerService.create(next);onSaved(saved);onClose()}catch{setError('Could not save customer. Please try again.')}finally{setSaving(false)}};return <div className="modalBackdrop" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget)onClose()}}><section className="customerModal" role="dialog" aria-modal="true" aria-labelledby="customer-modal-title"><div className="modalHeader"><div><p className="muted">{editing?'Update customer profile':'Create a complete customer profile'}</p><h2 id="customer-modal-title">{editing?'Edit customer':'Add customer'}</h2></div><button type="button" className="icon" aria-label="Close customer form" onClick={onClose}><X/></button></div><form className="form" onSubmit={save}><div className="formgrid"><label>Full name *<input autoFocus value={customer.fullName} onChange={event=>update('fullName',event.target.value)} placeholder="Customer name" required/></label><label>Display name<input value={customer.name} onChange={event=>update('name',event.target.value)} placeholder="Optional"/></label><label>Email<input type="email" value={customer.email} onChange={event=>update('email',event.target.value)} placeholder="name@example.com"/></label><label>Phone *<input value={customer.phone} onChange={event=>update('phone',event.target.value)} placeholder="+961 ..." required/></label><label>Company<input value={customer.company} onChange={event=>update('company',event.target.value)}/></label><label>Type<select value={customer.type} onChange={event=>update('type',event.target.value)}><option value="">Select customer type</option><option>Individual</option><option>Business</option></select></label><label>Address<input value={customer.address} onChange={event=>update('address',event.target.value)}/></label><label>Area<input value={customer.area} onChange={event=>update('area',event.target.value)}/></label><label>City<input value={customer.city} onChange={event=>update('city',event.target.value)}/></label><label>Joined date<input type="date" value={customer.joinedDate} onChange={event=>update('joinedDate',event.target.value)}/></label><label>Preferred payment<input value={customer.preferredPayment} onChange={event=>update('preferredPayment',event.target.value)}/></label><label>Status<select value={customer.status} onChange={event=>update('status',event.target.value)}><option value="">Select status</option><option>Active</option><option>VIP</option><option>Inactive</option></select></label><div className="customerMetrics full" aria-label="Customer metrics"><span><b>{metrics.ordersCount}</b> orders</span><span><b>${metrics.totalSpent.toFixed(2)}</b> total spent</span><span><b>{metrics.lastOrder}</b> last order</span></div><label className="full">Notes<textarea value={customer.notes} onChange={event=>update('notes',event.target.value)} placeholder="Helpful delivery or account notes"/></label></div>{error&&<p className="error modalError">{error}</p>}<div className="formactions"><button type="button" className="btn" onClick={onClose}>Cancel</button><button className="btn primary" type="submit" disabled={saving}>{saving?'Saving...':editing?'Save changes':'Add customer'}</button></div></form></section></div>}
function CustomerEdit(){const nav=useNavigate();const{id}=useParams();const[customer,setCustomer]=useState<Customer|null>(null);const[orders,setOrders]=useState<Order[]>([]);const[error,setError]=useState('');useEffect(()=>{Promise.all([customerService.list(),orderService.list()]).then(([customers,loaded])=>{setCustomer(customers.find(item=>item.id===id)||null);setOrders(loaded)}).catch(()=>setError('Unable to load customer data.'))},[id]);if(error)return <div className="page"><p className="error">{error}</p></div>;if(!customer)return <div className="page"><p>Customer not found.</p><button className="btn" onClick={()=>nav('/customers')}>Back to customers</button></div>;return <CustomerModal initial={customer} metrics={customerMetrics(customer,orders)} onClose={()=>nav(`/customers/${id}`)} onSaved={()=>nav(`/customers/${id}`)}/> }
function CustomerDetails(){const nav=useNavigate();const {id}=useParams();const [customer,setCustomer]=useState<Customer|null>(null);const [orders,setOrders]=useState<Order[]>([]);const [error,setError]=useState('');useEffect(()=>{Promise.all([customerService.list(),orderService.list()]).then(([customers,loaded])=>{setCustomer(customers.find(c=>c.id===id)||null);setOrders(loaded)}).catch(()=>setError('Unable to load customer data.'))},[id]);if(error)return <div className="page"><p className="error">{error}</p></div>;if(!customer)return <div className="page"><p>Customer not found.</p><button className="btn" onClick={()=>nav('/customers')}>Back to customers</button></div>;const linked=customerOrders(customer,orders);return <div className="page"><div className="toolbar"><div><p className="muted">Customer profile</p><h2>{customer.fullName||customer.name}</h2></div><div><button className="btn" onClick={()=>nav('/customers')}>Back</button><button className="btn primary" onClick={()=>nav(`/customers/${customer.id}/edit`)}><Edit3 size={15}/>Edit</button></div></div><div className="card profileCard"><div className="bigavatar">{(customer.fullName||customer.name).split(' ').map(x=>x[0]).join('').slice(0,2)}</div><div><h3>{customer.company||customer.type}</h3><p>{customer.email||'No email'} ? {customer.phone||'No phone'}</p><p>{customer.address||'No address'}{customer.area?`, ${customer.area}`:''}, {customer.city}</p><p className="muted">Joined {customer.joinedDate} ? {customer.preferredPayment}</p></div></div><div className="stats"><Stat label="Orders" value={String(linked.length)}/><Stat label="Total spent" value={`$${linked.reduce((sum,o)=>sum+Number(o.total||0),0).toFixed(2)}`}/><Stat label="Status" value={customer.status}/></div><section className="card"><div className="sectionTitle"><h3>Order history</h3><span className="muted">{linked.length} linked orders</span></div>{linked.length?<OrderTable rows={linked}/>:<p className="muted">No orders linked to this customer yet.</p>}</section></div>}
const customerMetrics=(customer:Customer,orders:Order[]):Pick<Customer,'ordersCount'|'totalSpent'|'lastOrder'>=>{const linked=customerOrders(customer,orders);const last=[...linked].sort((a,b)=>new Date(b.date||b.updatedAt).getTime()-new Date(a.date||a.updatedAt).getTime())[0];return {ordersCount:linked.length,totalSpent:linked.reduce((sum,o)=>sum+Number(o.total||0),0),lastOrder:last?.date||'—'}};
function Customers(){const[rows,setRows]=useState<Customer[]>([]);const[orders,setOrders]=useState<Order[]>([]);const[q,setQ]=useState('');const[modal,setModal]=useState<Customer|null|undefined>(undefined);const[message,setMessage]=useState('');useEffect(()=>{Promise.all([customerService.list(),orderService.list()]).then(([customers,loaded])=>{setRows(customers);setOrders(loaded)}).catch(()=>{setRows([]);setOrders([])})},[]);const filtered=rows.filter(c=>`${c.name} ${c.fullName} ${c.email} ${c.phone}`.toLowerCase().includes(q.toLowerCase()));const remove=async(id:string)=>{if(confirm('Delete this customer? Their orders will be kept.')){await customerService.remove(id);setRows(current=>current.filter(c=>c.id!==id));setMessage('Customer deleted.')}};const saved=(customer:Customer)=>{setRows(current=>{const exists=current.some(item=>item.id===customer.id);return exists?current.map(item=>item.id===customer.id?customer:item):[customer,...current]});setMessage(modal?'Customer updated successfully.':'Customer added successfully.');};return <div className="page"><div className="toolbar"><div><p className="muted">Customer profiles and order history</p><h2>Customers</h2></div><div className="customerActions"><div className="search"><Search size={16}/><input placeholder="Search customers" value={q} onChange={e=>setQ(e.target.value)}/></div><button className="btn primary" onClick={()=>setModal(null)}><Plus/>Add customer</button></div></div>{message&&<p className="successMessage" role="status">{message}</p>}<div className="customergrid">{filtered.map(c=>{const linked=customerOrders(c,orders);const total=linked.reduce((sum,o)=>sum+Number(o.total||0),0);const last=[...linked].sort((a,b)=>new Date(b.date||b.updatedAt).getTime()-new Date(a.date||a.updatedAt).getTime())[0];return <div className="card customerCard" key={c.id}><div className="customerTop"><div className="bigavatar">{(c.fullName||c.name).split(' ').map(x=>x[0]).join('').slice(0,2)}</div><div><button className="icon" aria-label={`Edit ${c.name}`} onClick={()=>setModal(c)}><Edit3 size={15}/></button><button className="icon" aria-label={`Delete ${c.name}`} onClick={()=>remove(c.id)}><Trash2 size={15}/></button></div></div><h3>{c.fullName||c.name} <span className="count">{c.status}</span></h3><p>{c.email||'No email'} ? {c.phone||'No phone'}</p><p>{c.address||'No address'}{c.area?`, ${c.area}`:''}, {c.city}</p><div className="customerMeta"><span>{linked.length} orders</span><b>${total.toFixed(2)}</b><span>Last: {last?.date||'?'}</span></div><Link className="btn" to={`/customers/${c.id}`}>View customer details</Link></div>})}</div>{!filtered.length&&<div className="card"><p className="muted">No customers found.</p></div>}{modal!==undefined&&<CustomerModal initial={modal} metrics={modal?customerMetrics(modal,orders):{ordersCount:0,totalSpent:0,lastOrder:'—'}} onClose={()=>setModal(undefined)} onSaved={saved}/>}</div>}
/* Hawn daftar l-sawa2i2 w ta3yin l-talabat b-shakel wadih. */
/* 3: hna kel driver byshouf assignments taba3o bas, w by2dar yzed unassigned order aw yshilo. */
function DriverModal({initial,onClose,onSaved}:{initial?:Driver;onClose:()=>void;onSaved:(driver:Driver)=>void}){const blank=():Driver=>({id:crypto.randomUUID(),name:'',phone:'',vehicle:'',plate:'',currentArea:'',status:'Available',deliveries:0,notes:''});const[form,setForm]=useState<Driver>(initial?normalizeDriver(initial):blank());const[error,setError]=useState('');const change=(field:keyof Driver,value:string)=>setForm(current=>({...current,[field]:field==='deliveries'?Math.max(0,Number(value)||0):value} as Driver));const save=async(e:React.FormEvent)=>{e.preventDefault();if(!form.name.trim()||!form.phone.trim()||!form.vehicle.trim()||!form.plate.trim()||!form.currentArea.trim()){setError('Name, phone, vehicle, plate, and current area are required.');return}const saved=initial?await driverService.update(form.id,form):await driverService.create(form);onSaved(normalizeDriver(saved));onClose()};return <div className="modalBackdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><form className="modal driverModal" onSubmit={save}><div className="modalHeader"><div><p className="muted">{initial?'Update driver details':'Add a driver'}</p><h2>{initial?'Edit driver':'New driver'}</h2></div><button type="button" className="icon" onClick={onClose} aria-label="Close"><X/></button></div>{error&&<p className="error">{error}</p>}<div className="formgrid"><label>Name<input value={form.name} onChange={e=>change('name',e.target.value)}/></label><label>Phone<input value={form.phone} onChange={e=>change('phone',e.target.value)}/></label><label>Vehicle<input value={form.vehicle} onChange={e=>change('vehicle',e.target.value)}/></label><label>Plate<input value={form.plate} onChange={e=>change('plate',e.target.value)}/></label><label>Current area<input value={form.currentArea} onChange={e=>change('currentArea',e.target.value)}/></label><label>Status<select value={form.status} onChange={e=>change('status',e.target.value)}><option>Available</option><option>On delivery</option><option>Offline</option></select></label><label className="full">Notes<textarea value={form.notes||''} onChange={e=>change('notes',e.target.value)}/></label></div><div className="modalActions"><button type="button" className="btn" onClick={onClose}>Cancel</button><button className="btn primary" type="submit">{initial?'Save changes':'Add driver'}</button></div></form></div>}
function Drivers(){const[rows,setRows]=useState<Driver[]>([]);const[orders,setOrders]=useState<Order[]>([]);const[q,setQ]=useState('');const[editing,setEditing]=useState('');const[orderToAssign,setOrderToAssign]=useState('');const[modal,setModal]=useState<Driver|null|undefined>(undefined);const[message,setMessage]=useState('');useEffect(()=>{Promise.all([driverService.list(),orderService.list()]).then(([d,o])=>{const linked=linkOrdersToDrivers(o,d);setRows(d);setOrders(linked);linked.forEach((order,index)=>{if(order.driverId&&(order.driverId!==o[index]?.driverId||order.driver!==o[index]?.driver))void orderService.update(order.id,{driverId:order.driverId,driver:order.driver})})})},[]);const assign=async(orderId:string,driverId:string)=>{const latest=linkOrdersToDrivers(await orderService.list(),rows);const current=latest.find(o=>o.id===orderId);if(driverId&&current?.driverId&&current.driverId!==driverId){setMessage(`This order is already assigned to ${current.driver}. Unassign it first.`);return}const d=rows.find(x=>x.id===driverId);await orderService.update(orderId,{driverId:driverId||undefined,driver:d?.name||'Unassigned'});setOrders(linkOrdersToDrivers(await orderService.list(),rows));setOrderToAssign('')};const save=(driver:Driver)=>{setRows(current=>current.some(d=>d.id===driver.id)?current.map(d=>d.id===driver.id?driver:d):[driver,...current]);setMessage('Driver saved successfully.')};const remove=async(driver:Driver)=>{const latest=linkOrdersToDrivers(await orderService.list(),rows);if(latest.some(o=>o.driverId===driver.id)){setMessage(`Cannot delete ${driver.name}: unassign or reassign all assigned orders first.`);return}if(confirm(`Delete ${driver.name}?`)){await driverService.remove(driver.id);setRows(current=>current.filter(d=>d.id!==driver.id));setMessage('Driver deleted.')}};const visible=rows.filter(d=>`${d.name} ${d.phone} ${d.currentArea} ${d.vehicle}`.toLowerCase().includes(q.toLowerCase()));return <div className="page"><div className="toolbar"><div><p className="muted">Fleet availability and assignments</p><h2>Drivers</h2></div><div className="customerActions"><div className="search"><Search size={16}/><input placeholder="Search drivers..." value={q} onChange={e=>setQ(e.target.value)}/></div><button className="btn primary" onClick={()=>setModal(null)}><Plus/>Add driver</button></div></div>{message&&<p className="successMessage" role="status">{message}</p>}<div className="drivergrid">{visible.map(d=>{const assigned=orders.filter(o=>o.driverId===d.id);const available=orders.filter(o=>!o.driverId);return <section className="card driverCard" key={d.id}><div className="driverTop"><div className="bigavatar">{d.name.split(' ').map(x=>x[0]).join('')}</div><span className={'badge driver-'+d.status.toLowerCase().replace(' ','-')}><i/>{d.status}</span></div><div className="cardActions"><button className="icon" aria-label={`Edit ${d.name}`} onClick={()=>setModal(d)}><Edit3 size={15}/></button><button className="icon" aria-label={`Delete ${d.name}`} onClick={()=>remove(d)}><Trash2 size={15}/></button></div><h3>{d.name}</h3><p>{d.phone}</p><p>{d.vehicle} · {d.plate}</p><p><MapPin size={14}/> {d.currentArea}</p><div className="customerMeta"><span>{assigned.length} assignments</span></div><button className="btn" onClick={()=>setEditing(editing===d.id?'':d.id)}>Manage assignments</button>{editing===d.id&&<div className="assignmentList"><label className="assignmentAdd">Assign an available order<select value={orderToAssign} onChange={e=>{setOrderToAssign(e.target.value);if(e.target.value)assign(e.target.value,d.id)}}><option value="">Choose an order</option>{available.map(o=><option key={o.id} value={o.id}>{o.id} - {o.city}</option>)}</select></label>{assigned.length?assigned.map(o=><label key={o.id}>{o.id}<select value={d.id} onChange={()=>assign(o.id,'')}><option value={d.id}>{d.name}</option><option value="">Unassign from this driver</option></select></label>):<p className="muted">No orders assigned to this driver.</p>}</div>}</section>})}</div>{!visible.length&&<div className="card"><p className="muted">No drivers found.</p></div>}{modal!==undefined&&<DriverModal initial={modal||undefined} onClose={()=>setModal(undefined)} onSaved={save}/>}</div>}

/* 5: hna analytics page b7ot charts 3ashan insights w performance summary. */
function Analytics(){const[orders,setOrders]=useState<Order[]>([]);const[customers,setCustomers]=useState<Customer[]>([]);const[drivers,setDrivers]=useState<Driver[]>([]);useEffect(()=>{Promise.all([orderService.list(),customerService.list(),driverService.list()]).then(([o,c,d])=>{setOrders(o);setCustomers(c);setDrivers(d)}).catch(()=>{setOrders([]);setCustomers([]);setDrivers([])})},[]);const totals=orderTotals(orders);const onTime=totals.delivered?Math.round((totals.delivered/orders.length)*100):0;const chart=dailyOrders(orders);const byStatus=statusOptions.map(status=>({status,count:orders.filter(o=>o.status===status).length}));return <div className="page"><div className="toolbar"><div><p className="muted">Performance insights from persisted orders</p><h2>Analytics</h2></div></div><div className="stats"><Stat label="Delivery completion" value={`${onTime}%`}/><Stat label="Average order value" value={`$${(orders.length?totals.revenue/orders.length:0).toFixed(2)}`}/><Stat label="Active customers" value={String(customers.filter(c=>c.status!=='Inactive').length)}/><Stat label="Active drivers" value={String(drivers.filter(d=>d.status!=='Offline').length)}/></div><section className="card chartcard"><h3>Daily order volume and revenue</h3><ResponsiveContainer width="100%" height={320}><AreaChart data={chart}><XAxis dataKey="day"/><YAxis yAxisId="orders" allowDecimals={false}/><Tooltip/><Area yAxisId="orders" type="monotone" dataKey="orders" stroke="#14b89a" fill="#14b89a" fillOpacity={.15}/></AreaChart></ResponsiveContainer></section><section className="card"><h3>Status breakdown</h3><div className="customerMeta">{byStatus.map(item=><span key={item.status}>{item.status}: <b>{item.count}</b></span>)}</div></section></div>}
/* 2: hna settings page b7ot preferences 3ashan workspace personalized. */
/* 5: hna company details b7ot profile wa2e3e w operations info la l-workspace ybayyen pro. */
function SettingsPage(){const[saved,setSaved]=useState(false);return <div className="page"><div className="toolbar"><div><p className="muted">Workspace preferences and company information</p><h2>Settings</h2></div><span className="settingsStatus">Beirut hub · Active</span></div><div className="settingsGrid"><section className="card form"><div className="settingsSectionHeading"><div><h3>Company profile</h3><p className="muted">The details customers see on delivery updates and invoices.</p></div><span className="profileMark">RL</span></div><div className="formgrid"><label>Company name<input defaultValue="RouteLy Logistics"/></label><label>Legal name<input defaultValue="RouteLy Logistics SAL"/></label><label>Contact email<input type="email" defaultValue="hello@routely.lb"/></label><label>Phone number<input defaultValue="+961 1 555 824"/></label><label className="full">Office address<input defaultValue="Hamra Street, Beirut, Lebanon"/></label><label>Website<input defaultValue="www.routely.lb"/></label><label>Tax ID<input defaultValue="LB-LOG-2026-0842"/></label></div><div className="formactions"><button type="button" className="btn primary" onClick={()=>setSaved(true)}>Save changes</button></div>{saved&&<p className="successMessage" role="status">Company profile saved.</p>}</section><section className="card settingsInfo"><div className="settingsSectionHeading"><div><h3>Operations</h3><p className="muted">Default delivery and workspace settings.</p></div><Settings size={20}/></div><div className="settingsList"><div><span>Primary hub</span><b>Hamra, Beirut</b></div><div><span>Service area</span><b>Greater Beirut and all Lebanon</b></div><div><span>Delivery hours</span><b>Monday–Saturday · 08:00–20:00</b></div><div><span>Default currency</span><b>USD — US Dollar</b></div><div><span>Timezone</span><b>Beirut · GMT+3</b></div><div><span>Support email</span><b>support@routely.lb</b></div></div></section></div><section className="card companyNote"><div className="companyIcon"><Truck size={20}/></div><div><h3>About RouteLy</h3><p>RouteLy is a Beirut-based logistics workspace helping local teams coordinate reliable last-mile deliveries across Lebanon. Our Hamra operations hub connects customers, drivers, and dispatchers in one live view.</p></div></section></div>}
/* 4: hna login/register screens b7ot feedback wadih w support lal user aw admin. */
function Login({onLogin}:{onLogin:(user:AuthUser)=>void}){const[email,setEmail]=useState('');const[password,setPassword]=useState('');const[error,setError]=useState('');const submit=(event:React.FormEvent)=>{event.preventDefault();try{onLogin(authService.login(email,password))}catch(err){setError(err instanceof Error?err.message:'Could not sign in.')}};return <AuthShell title="Welcome back" subtitle="Sign in to manage your deliveries"><form className="card form" onSubmit={submit}>{error&&<p className="error">{error}</p>}<label>Email<input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Password<input type="password" required value={password} onChange={e=>setPassword(e.target.value)}/></label><button className="btn primary">Sign in</button><p className="muted">New admin? <Link to="/register">Create an admin account</Link></p></form></AuthShell>}
function Register({onLogin}:{onLogin:(user:AuthUser)=>void}){const[form,setForm]=useState({name:'',email:'',password:'',phone:'',city:'Beirut',jobTitle:'Operations manager'});const[error,setError]=useState('');const set=(key:keyof typeof form,value:string)=>setForm(current=>({...current,[key]:value}));const submit=async(event:React.FormEvent)=>{event.preventDefault();try{onLogin(await authService.register(form))}catch(err){setError(err instanceof Error?err.message:'Could not create account.')}};return <AuthShell title="Create admin account" subtitle="Set up your RouteLy workspace"><form className="card form" onSubmit={submit}>{error&&<p className="error">{error}</p>}<label>Full name<input required value={form.name} onChange={e=>set('name',e.target.value)}/></label><label>Email<input type="email" required value={form.email} onChange={e=>set('email',e.target.value)}/></label><label>Password<input type="password" minLength={6} required value={form.password} onChange={e=>set('password',e.target.value)}/></label><label>Phone<input value={form.phone} onChange={e=>set('phone',e.target.value)}/></label><label>City<input value={form.city} onChange={e=>set('city',e.target.value)}/></label><button className="btn primary">Register as admin</button><p className="muted">Already registered? <Link to="/">Sign in</Link></p></form></AuthShell>}
function AuthShell({title,subtitle,children}:{title:string;subtitle:string;children:React.ReactNode}){return <div className="authpage"><div className="authbrand"><div className="logo"><Truck size={20}/></div><b>Route<span>ly</span></b></div><h1>{title}</h1><p className="muted">{subtitle}</p>{children}</div>}
function ProfilePage({user,onUpdate,onLogout}:{user:AuthUser;onUpdate:(user:AuthUser)=>void;onLogout:()=>void}){const[form,setForm]=useState<ProfileUpdate>({name:user.name,email:user.email,phone:user.phone,city:user.city,jobTitle:user.jobTitle});const[saved,setSaved]=useState(false);const[error,setError]=useState('');const set=(key:keyof ProfileUpdate,value:string)=>setForm(current=>({...current,[key]:value}));const save=()=>{try{onUpdate(authService.updateProfile(user.id,form));setSaved(true);setError('')}catch(err){setError(err instanceof Error?err.message:'Could not update profile.')}};return <div className="page formpage"><div className="toolbar"><div><p className="muted">Account</p><h2>My profile</h2></div><button className="btn" onClick={onLogout}>Log out</button></div><section className="card form"><h3>Personal details</h3>{error&&<p className="error">{error}</p>}{saved&&<p className="success">Profile saved successfully.</p>}<div className="formgrid"><label>Full name<input value={form.name} onChange={e=>set('name',e.target.value)}/></label><label>Email<input type="email" value={form.email} onChange={e=>set('email',e.target.value)}/></label><label>Phone<input value={form.phone} onChange={e=>set('phone',e.target.value)}/></label><label>City<input value={form.city} onChange={e=>set('city',e.target.value)}/></label><label className="full">Job title<input value={form.jobTitle} onChange={e=>set('jobTitle',e.target.value)}/></label></div><div className="formactions"><button type="button" className="btn primary" onClick={save}>Save profile</button></div></section></div>}
/* 7: hna render boot b7ot app root 3ashan router ybda l-navigation. */
createRoot(document.getElementById('root')!).render(<BrowserRouter><App/></BrowserRouter>);
